SELECT id AS "id", ledger_id AS "ledgerId", run_id AS "runId",
       command_id AS "commandId", device_id AS "deviceId",
       method AS "method", state AS "state", attempts AS "attempts",
       created_at::text AS "createdAt", delivered_at::text AS "deliveredAt"
  FROM command_outbox
 WHERE tenant_id = #{param1}
 AND state = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT id AS "id", run_id AS "runId", plate_barcode AS "plateBarcode",
       source_resource_id AS "sourceResourceId",
       target_resource_id AS "targetResourceId",
       status AS "status", error_code AS "errorCode",
       error_message AS "errorMessage", created_at::text AS "createdAt"
  FROM transfer_transaction
 WHERE tenant_id = #{param1}
 AND status = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT id AS "id", plate_barcode AS "plateBarcode",
       resource_id AS "resourceId", evidence_type AS "evidenceType",
       run_id AS "runId", operator AS "operator", note AS "note",
       created_at::text AS "createdAt"
  FROM position_evidence
 WHERE tenant_id = #{param1}
 AND plate_barcode = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT DISTINCT resource_id FROM workflow_node
 WHERE tenant_id = #{param1} AND workflow_id = #{param2}
   AND node_type = 'task' AND resource_id IS NOT NULL

SELECT method AS "method", p50_ms AS "p50Ms", p90_ms AS "p90Ms",
       min_ms AS "minMs", max_ms AS "maxMs", sample_count AS "sampleCount"
  FROM duration_model
 WHERE tenant_id = #{param1}
 ORDER BY sample_count DESC LIMIT #{param2}

